def create_or_update_translation_obj(
    model, object_id, content_type, language, translation
):
    obj = model.objects.filter(
        object_id=object_id,
        content_type=content_type,
        language=language,
    ).first()
    if obj is None:
        obj = model(
            object_id=object_id,
            content_type=content_type,
            language=language,
            translation=translation,
        )
        obj.save()
    else:
        obj.translation = translation
        obj.save()

    return obj


